import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1787092618000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Three environment variables; only the first is required.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>RUSTPAD_URL</code></td><td>yes</td><td>Base URL of the instance, e.g. <code>https://rustpad.example.net</code></td></tr><tr><td><code>RUSTPAD_READ_ONLY</code></td><td>no</td><td><code>true</code> registers only the read tools</td></tr><tr><td><code>RUSTPAD_INSECURE_TLS</code></td><td>no</td><td><code>true</code> accepts self-signed certificates (scoped to this connection only)</td></tr></tbody></table><h2 id="one-url-for-everything" tabindex="-1">One URL for everything <a class="header-anchor" href="#one-url-for-everything" aria-label="Permalink to “One URL for everything”">​</a></h2><p><code>RUSTPAD_URL</code> serves three purposes: the HTTP API (<code>/api/text</code>, <code>/api/stats</code>), the collaboration WebSocket (<code>http</code>/<code>https</code> is mapped to <code>ws</code>/<code>wss</code>), and the share links the tools return (<code>&lt;RUSTPAD_URL&gt;/#&lt;pad-id&gt;</code>). If your instance sits behind a reverse proxy, that proxy must forward WebSocket upgrades on <code>/api/socket/…</code>.</p><p>The URL is validated on start: only <code>http:</code>/<code>https:</code>, no embedded credentials, no query string or fragment. A plain-<code>http</code> URL to a non-loopback host starts with a warning — everything, including full pad content, would travel unencrypted. A malformed URL exits instead of limping along.</p><h2 id="boolean-semantics" tabindex="-1">Boolean semantics <a class="header-anchor" href="#boolean-semantics" aria-label="Permalink to “Boolean semantics”">​</a></h2><p>The two flags compare against exactly the string <code>true</code>. <code>True</code>, <code>1</code> or <code>yes</code> count as <strong>false</strong> — deliberately strict, and the reason the server prints a banner on start when read-only or insecure-TLS mode is actually active.</p><h2 id="ephemerality" tabindex="-1">Ephemerality <a class="header-anchor" href="#ephemerality" aria-label="Permalink to “Ephemerality”">​</a></h2><p>Rustpad keeps documents in memory; they are lost when the server restarts and after 24 hours without an open connection. If you want pads to survive, run the Rustpad instance itself with <code>SQLITE_URI</code> (see the <a href="https://github.com/ekzhang/rustpad#configuration" target="_blank" rel="noreferrer">Rustpad README</a>) — nothing changes on the rustpad-mcp side.</p><h2 id="limits-worth-knowing" tabindex="-1">Limits worth knowing <a class="header-anchor" href="#limits-worth-knowing" aria-label="Permalink to “Limits worth knowing”">​</a></h2><ul><li>Documents are capped at 256 KiB by Rustpad itself; the server checks before sending and refuses edits that would exceed it.</li><li>Tool results are budgeted to ~200 000 characters; a larger pad is truncated with an explicit notice rather than silently cut.</li><li>Every network wait has a wall-clock timeout (15–20 s); a hostile or hung upstream costs a failed tool call, never a hung server.</li></ul>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};